import{_ as e,o,c as a,a2 as n}from"./chunks/framework.BN2sqjC1.js";const g=JSON.parse('{"title":"Condivisione e gruppi","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/condivisione-gruppi.md","filePath":"user-guide/condivisione-gruppi.md"}'),t={name:"user-guide/condivisione-gruppi.md"};function r(l,i,s,c,d,u){return o(),a("div",null,[...i[0]||(i[0]=[n('<h1 id="condivisione-e-gruppi" tabindex="-1">Condivisione e gruppi <a class="header-anchor" href="#condivisione-e-gruppi" aria-label="Permalink to &quot;Condivisione e gruppi&quot;">​</a></h1><p>La condivisione è disponibile solo per i <strong>vault condivisi</strong> (non cifrati), mai per quelli privati. Si può condividere l&#39;<strong>intero vault</strong>, una <strong>cartella</strong> o un singolo <strong>documento</strong> (le note, gli allegati e i file di lavagna/disegno).</p><h2 id="condividere" tabindex="-1">Condividere <a class="header-anchor" href="#condividere" aria-label="Permalink to &quot;Condividere&quot;">​</a></h2><ol><li>Clic destro su una cartella o nota nell&#39;albero → <em>Condividi…</em> (oppure <em>Condividi la nota corrente…</em> dalla palette; per tutto il vault: <em>Condividi l&#39;intero vault…</em>).</li><li>Cercate <strong>persone e gruppi</strong> e aggiungeteli come destinatari.</li><li>Scegliete il <strong>livello</strong> per ciascuno: <strong>Lettore</strong> (sola lettura), <strong>Editor</strong> (modifica), <strong>Gestore</strong> (modifica e gestione della condivisione).</li><li><em>Condividi</em>: i destinatari ricevono un <strong>invito</strong>.</li></ol><p>Le <em>Condivisioni esistenti</em> si vedono e si modificano nella stessa finestra (cambiare livello, aggiungere o rimuovere destinatari, <strong>revocare</strong>). Revocare interrompe subito l&#39;accesso.</p><h2 id="ricevere-un-invito" tabindex="-1">Ricevere un invito <a class="header-anchor" href="#ricevere-un-invito" aria-label="Permalink to &quot;Ricevere un invito&quot;">​</a></h2><p>Gli inviti compaiono in fondo alla barra laterale destra, o nell&#39;intestazione se la barra è chiusa (&quot;1 invito&quot;), e in <em>Impostazioni → Condivisione</em>, e nella Web UI alla pagina <em>Condivisioni</em>. <strong>Accettate</strong> o <strong>rifiutate</strong>. Un invito accettato diventa un <strong>mount</strong>: un vault separato, intitolato come la condivisione, che si apre con <em>Apri</em>. Il mount è a tutti gli effetti un altro vault: i link, i backlink, la ricerca e il grafo <strong>non attraversano</strong> il vostro vault personale e il mount.</p><p>Lo stato del vault (in fondo alla barra laterale destra, o nell&#39;intestazione se è chiusa) mostra il vostro permesso (es. &quot;Lettore · sola lettura&quot;), e la scheda <em>Statistiche</em> elenca con chi è condivisa la nota; con il permesso di lettore l&#39;editor non accetta modifiche e l&#39;albero non offre di creare nulla.</p><h2 id="quando-la-condivisione-termina" tabindex="-1">Quando la condivisione termina <a class="header-anchor" href="#quando-la-condivisione-termina" aria-label="Permalink to &quot;Quando la condivisione termina&quot;">​</a></h2><p>Se il proprietario revoca la condivisione, l&#39;app chiede cosa fare della vostra copia: <strong>eliminarla</strong> oppure <strong>conservarla</strong> come vault normale, scollegato (in una cartella indicata). Potete anche <em>Rimuovere dal dispositivo</em> un mount, con la stessa scelta; il proprietario mantiene i suoi file.</p><h2 id="consigli-sulla-collaborazione" tabindex="-1">Consigli sulla collaborazione <a class="header-anchor" href="#consigli-sulla-collaborazione" aria-label="Permalink to &quot;Consigli sulla collaborazione&quot;">​</a></h2><p>La collaborazione è <strong>asincrona</strong>: ciascuno lavora sulla propria copia e le modifiche si uniscono alla sincronizzazione. L&#39;unione automatica è garantita per le note Markdown; per lavagne, disegni e basi, se due persone modificano lo stesso file nello stesso intervallo, si crea una <strong>copia di conflitto</strong> (nessuna versione si perde). Lo spazio usato conta sulla <strong>quota del proprietario</strong> della condivisione.</p><h2 id="gruppi" tabindex="-1">Gruppi <a class="header-anchor" href="#gruppi" aria-label="Permalink to &quot;Gruppi&quot;">​</a></h2><p>I <strong>gruppi</strong> li crea e li gestisce l&#39;amministratore (console web). Servono per condividere con molte persone in una volta e per distribuire configurazioni. Non sono importati da altri sistemi. Se non trovate un gruppo nella ricerca dei destinatari, chiedete all&#39;amministratore.</p>',14)])])}const v=e(t,[["render",r]]);export{g as __pageData,v as default};
